  const act=aS/wS,inh=iS/wS;
  const bg1=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2=Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg3=Math.sin(sx*0.08+Math.sin(sy*0.05+t)*2+t*0.6)*0.15;
  const bg=bg1+bg2+bg3;
  const d1=Math.sqrt((sx-cx)**2+(sy-cy)**2),a1=Math.atan2(sy-cy,sx-cx);
  const sp1=(Math.sin(d1*0.05-a1*3-t*1.5)+Math.sin(d1*0.04+a1*4-t*1.2))*0.4;
  const v2x=180+Math.sin(t*0.4)*60,v2y=80+Math.cos(t*0.3)*40;
  const d2=Math.sqrt((sx-v2x)**2+(sy-v2y)**2),a2=Math.atan2(sy-v2y,sx-v2x);
