  const spiral=sp1+sp2+sp3;
  const raw=act-inh*0.7+bg*0.3+spiral;
  const fb=Math.sin(raw*2.5)*0.15;
  const reaction=Math.tanh((raw+fb)*2.2);
  const cw=Math.sin(sx*0.05+t*0.7)*Math.cos(sy*0.04-t*0.5)*0.3;
  const cell=Math.tanh((Math.sin((sx+cw)*0.15)*Math.sin((sy+cw)*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const grain=Math.sin(sx*0.4+sy*0.3+t*3)*Math.sin(sx*0.3-sy*0.4-t*2.5)*0.08;
  const blend=reaction*0.6+cell*0.25+grain,v=blend*0.5+0.5;
  const pal=[[5,12,52],[10,45,85],[15,95,105],[25,155,130],[120,190,100],[210,200,80],[220,150,60],[195,95,65],[160,55,75],[90,25,60],[40,15,55],[5,12,52]];
