  const bR=pal[i][0]+(pal[i+1][0]-pal[i][0])*f;
  const bG=pal[i][1]+(pal[i+1][1]-pal[i][1])*f;
  const bB=pal[i][2]+(pal[i+1][2]-pal[i][2])*f;
  return[
    Math.min(255,(bR*lum*edge+glow*200))|0,
    Math.min(255,(bG*lum*edge+glow*220))|0,
    Math.min(255,(bB*lum*edge+glow*255))|0
  ];
}
